/* CVE-2022-0847 "Dirty Pipe" — key primitive (kernel 5.8 .. 5.16.11)
 * An uninitialized pipe_buffer.flags lets a reader splice() pages and then
 * write past a file's end into the page cache. The field that must NOT carry
 * PIPE_BUF_FLAG_CAN_MERGE is reset by the fix. */
#define PIPE_BUF_FLAG_CAN_MERGE 0x10
struct pipe_buffer {
    struct page *page;              /* +0x00 */
    unsigned int offset, len;       /* +0x08, +0x0c */
    const struct pipe_buf_operations *ops; /* +0x10 */
    unsigned int flags;             /* <-- which offset? */
    unsigned long private;          /* +0x20 */
};
